def positive_square_sum(values):
    total = 0
    for value in values:
        total += value**2 if value > 0 else 0
    return total

assert positive_square_sum([-2, 0, 3, 4]) == 25

#include <vector>
#include <cassert>
int main() {
    std::vector<int> values{1, 2, 3};
    for (int& value : values) {
        value *= 2;
    }
    assert((values == std::vector<int>{2, 4, 6}));
}

