#include <algorithm>
#include <vector>
#include <cassert>
int main() {
    int limit = 2;
    std::vector<int> values{1, 2, 3, 4};
    auto count = std::count_if(values.begin(), values.end(),
        [limit](int x) { return x > limit; });
    assert(count == 2);
}

